package com.google.javascript.rhino;

import com.google.common.base.Preconditions;
import com.google.javascript.rhino.IR;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class IR_tryFinally_TriageGen1Test {

    @Test
    public void testTryFinally_Success() {
        // Setup: tryBody must be a label name per Preconditions.checkState(tryBody.isLabelName())
        // and finallyBody must be a label name per Preconditions.checkState(finallyBody.isLabelName())
        Node tryBody = IR.labelName("tryLabel");
        Node finallyBody = IR.labelName("finallyLabel");

        Node result = IR.tryFinally(tryBody, finallyBody);

        // Verify result is not null
        assertNotNull("Resulting node should not be null", result);

        // Verify token type
        assertEquals("Token type should be TRY", Token.TRY, result.getType());

        // Verify children structure: tryBody, catchBody (copy of tryBody), finallyBody
        // The constructor is new Node(Token.TRY, tryBody, catchBody, finallyBody);
        assertEquals("First child should be tryBody", tryBody, result.getFirstChild());
        assertEquals("Third child should be finallyBody", finallyBody, result.getNthChild(2));

        // Verify catchBody is a copy/block based on the implementation logic
        Node catchBody = result.getNthChild(1);
        assertNotNull("Catch body should not be null", catchBody);
        assertTrue("Catch body should be a block type", catchBody.isBlock());
    }

    @Test(expected = IllegalStateException.class)
    public void testTryFinally_TryBodyNotLabelNameThrows() {
        // tryBody is a regular block, not a label name
        Node tryBody = IR.block();
        Node finallyBody = IR.labelName("finallyLabel");

        IR.tryFinally(tryBody, finallyBody);
    }

    @Test(expected = IllegalStateException.class)
    public void testTryFinally_FinallyBodyNotLabelNameThrows() {
        // finallyBody is a regular block, not a label name
        Node tryBody = IR.labelName("tryLabel");
        Node finallyBody = IR.block();

        IR.tryFinally(tryBody, finallyBody);
    }

    @Test(expected = IllegalStateException.class)
    public void testTryFinally_BothNotLabelNameThrows() {
        Node tryBody = IR.block();
        Node finallyBody = IR.block();

        IR.tryFinally(tryBody, finallyBody);
    }
}
